#include <queue>
#include <vector>
using namespace std;

class MKAverage {
private:
    static constexpr int MAX_VALUE = 100000;

    int m_, k_;
    queue<int> window;
    vector<int> counts;
    vector<long long> sums;

    void update(int value, int delta) {
        for (int i = value; i <= MAX_VALUE; i += i & -i) {
            counts[i] += delta;
            sums[i] += 1LL * value * delta;
        }
    }

    // Returns the sum of the smallest rank elements, including duplicates.
    long long smallestSum(int rank) const {
        int index = 0;
        long long result = 0;

        for (int step = 1 << 16; step > 0; step >>= 1) {
            int next = index + step;
            if (next <= MAX_VALUE && counts[next] <= rank) {
                index = next;
                rank -= counts[next];
                result += sums[next];
            }
        }

        return result + 1LL * rank * (index + 1);
    }

public:
    MKAverage(int m, int k)
        : m_(m), k_(k),
          counts(MAX_VALUE + 1, 0),
          sums(MAX_VALUE + 1, 0) {
    }

    void addElement(int num) {
        window.push(num);
        update(num, 1);

        if (static_cast<int>(window.size()) > m_) {
            update(window.front(), -1);
            window.pop();
        }
    }

    int calculateMKAverage() {
        if (static_cast<int>(window.size()) < m_) {
            return -1;
        }

        long long middleSum = smallestSum(m_ - k_) - smallestSum(k_);
        return static_cast<int>(middleSum / (m_ - 2 * k_));
    }
};

